<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue';import {ElMessage} from 'element-plus'
import {useRouter} from 'vue-router';import {api,errorMessage,user,query} from '../api/http'
const router=useRouter();const canUpload=computed(()=>user.value?.roles.includes('ROLE_ADMIN'));const candidates=ref<any[]>([]),finding=ref(false);let searchSequence=0;
async function findOwners(text=''){const seq=++searchSequence;finding.value=true;try{const data=await api<any>((owner.value==='export'?'/exports?':'/sales?')+query(owner.value==='export'?{keyword:text,size:20}:{q:text,size:20}));if(seq===searchSequence)candidates.value=data.rows}catch(e){if(seq===searchSequence)ElMessage.error(errorMessage(e))}finally{if(seq===searchSequence)finding.value=false}}
const recent=ref<any[]>([]);const historyLoading=ref(false);async function fetchRecent(){historyLoading.value=true;try{recent.value=await api<any[]>('/records/documents')}catch(e){ElMessage.error(errorMessage(e))}finally{historyLoading.value=false}}onMounted(fetchRecent)
const csv=ref<File|null>(null),pdf=ref<File|null>(null),owner=ref('export'),ownerId=ref(''),type=ref('INVOICE'),busy=ref(false),result=ref('')
watch(owner,()=>{ownerId.value='';candidates.value=[];void findOwners()});onMounted(()=>{if(canUpload.value)void findOwners()})
function fileChanged(e:Event,target:'csv'|'pdf'){const f=(e.target as HTMLInputElement).files?.[0]||null;if(f&&(!f.name.toLowerCase().endsWith('.'+target)||f.size===0||f.size>(target==='csv'?2:15)*1024*1024)){ElMessage.warning(target==='csv'?'UTF-8 CSV（2MB以下）を選択してください':'PDF（15MB以下）を選択してください');(e.target as HTMLInputElement).value='';if(target==='csv')csv.value=null;else pdf.value=null;return}if(target==='csv')csv.value=f;else pdf.value=f}
async function sendCsv(){if(busy.value||!canUpload.value)return;if(!csv.value)return ElMessage.warning('CSVを選択してください');busy.value=true;try{const form=new FormData();form.append('file',csv.value);const data=await api<any>('/imports/csv',{method:'POST',body:form});result.value=`輸出 ${data.createdExports} 件・包装明細 ${data.packingRows} 行を登録しました（DRAFT）。元資料と照合してください。`;ElMessage.success('取込み完了');await findOwners()}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
async function sendPdf(){if(busy.value||!canUpload.value)return;if(!pdf.value||!Number(ownerId.value))return ElMessage.warning('PDFと関連レコードを選択してください');busy.value=true;try{const form=new FormData();form.append('file',pdf.value);form.append('type',type.value);form.append(owner.value==='export'?'exportId':'orderId',ownerId.value);const data=await api<any>('/documents',{method:'POST',body:form});result.value=`PDF「${data.name}」を登録しました。`;pdf.value=null;ElMessage.success('PDFアップロード完了');await fetchRecent()}catch(e){ElMessage.error(errorMessage(e))}finally{busy.value=false}}
</script>
<template><h1 class="page-title">データ取込み</h1><div class="banner">初版は管理者のみアップロードできます。CSVは限定した列構成（1輸出につき1設備）を対象とします。画像・スキャンPDFの自動文字認識は対象外です。</div><el-alert v-if="!canUpload" title="閲覧ユーザーは登録済み書類のみ確認できます。取込みには管理者権限が必要です。" type="info" :closable="false"/><section v-if="canUpload" class="panel"><header class="panel-heading">CSVデータ取込み</header><div class="panel-body"><p>標準テンプレート: <a href="/samples/export-import-template.csv" download>export-import-template.csv</a></p><input type="file" accept=".csv,text/csv" @change="fileChanged($event,'csv')"/><div style="margin-top:15px"><el-button type="primary" :loading="busy" :disabled="!csv" @click="sendCsv">CSVを取込む</el-button></div><p class="data-note">UTF-8 CSV・2MB以下・包装300行まで。ヘッダと日付はテンプレートに従ってください。新規レコードは DRAFT 登録されるため、元資料を照合してください。</p></div></section><section v-if="canUpload" class="panel"><header class="panel-heading">原票PDFのアップロード</header><div class="panel-body"><el-form label-position="top"><el-row :gutter="18"><el-col :xs="24" :sm="12" :lg="8"><el-form-item label="関連先"><el-select v-model="owner" style="width:100%"><el-option label="輸出レコード" value="export"/><el-option label="販売レコード" value="order"/></el-select></el-form-item></el-col><el-col :xs="24" :sm="12" :lg="8"><el-form-item label="関連レコード（番号で検索）"><el-select v-model="ownerId" filterable remote :remote-method="findOwners" :loading="finding" placeholder="番号・取引先で検索" style="width:100%"><el-option v-for="item in candidates" :key="item.export_id||item.order_id" :value="String(item.export_id||item.order_id)" :label="(item.export_no||item.order_no)+' · '+item.customer_name"/></el-select></el-form-item></el-col><el-col :xs="24" :sm="12" :lg="8"><el-form-item label="書類種別"><el-select v-model="type" style="width:100%"><el-option v-for="t in ['INVOICE','PACKING_LIST','ORDER','CONTRACT','OTHER']" :key="t" :label="t" :value="t"/></el-select></el-form-item></el-col></el-row><input type="file" accept="application/pdf,.pdf" @change="fileChanged($event,'pdf')"/><div style="margin-top:15px"><el-button type="primary" :loading="busy" :disabled="!pdf||!ownerId" @click="sendPdf">PDFを登録</el-button></div></el-form><p class="data-note">ファイルは15MB以下のPDFのみ。元ファイルを変更せずにプレビューできます。</p></div></section><section v-if="result" class="panel"><header class="panel-heading">取込み結果</header><div class="panel-body"><p role="status">{{result}}</p></div></section><section class="panel"><header class="panel-heading">登録済み書類（最新80件）</header><div class="panel-body"><el-table :data="recent" v-loading="historyLoading" stripe border><el-table-column prop="file_name" label="ファイル名" min-width="220" show-overflow-tooltip/><el-table-column prop="document_type" label="種別" width="125"/><el-table-column prop="created_at" label="登録日時" min-width="155"/><el-table-column label="関連レコード" width="135"><template #default="s"><el-button size="small" @click="router.push(s.row.export_id?'/exports/'+s.row.export_id+'/documents':'/sales/'+s.row.order_id+'/documents')">原票を見る</el-button></template></el-table-column></el-table><p class="data-note">SYN26 書類はテスト用に生成した PDF です。実際の取込み監査ログとは異なります。</p></div></section></template>
